CREATE OR REPLACE FUNCTION public.jobber_member_shift_access(_user uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.access_decrypt(gate_code_enc) FROM public.profiles WHERE user_id=_user $$;
REVOKE ALL ON FUNCTION public.jobber_member_shift_access(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.jobber_member_shift_access(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.member_details_jobber_push() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; BEGIN FOR s IN SELECT id FROM public.subscriptions WHERE user_id=NEW.user_id AND status IN ('active','paused') LOOP PERFORM public.call_edge_function('jobber-sync',jsonb_build_object('action','sync_subscription','subscription_id',s.id)); END LOOP; RETURN NEW; END $$;
CREATE TRIGGER member_profile_jobber_push AFTER UPDATE OF address_line1,address_line2,city,zip,first_name,last_name,phone,gate_code_enc,parking_notes,pets,special_instructions,preferred_day,preferred_time ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.member_details_jobber_push();
CREATE TRIGGER member_home_jobber_push AFTER INSERT OR UPDATE ON public.home_notes FOR EACH ROW EXECUTE FUNCTION public.member_details_jobber_push();
CREATE TRIGGER member_car_jobber_push AFTER INSERT OR UPDATE ON public.car_wash_profiles FOR EACH ROW EXECUTE FUNCTION public.member_details_jobber_push();
CREATE OR REPLACE FUNCTION public.subscriptions_jobber_push() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR (to_jsonb(NEW)-'jobber_job_ids'-'jobber_client_id'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'jobber_job_ids'-'jobber_client_id'-'updated_at') THEN PERFORM public.call_edge_function('jobber-sync',jsonb_build_object('action','sync_subscription','subscription_id',NEW.id)); END IF; RETURN NEW; END $$;